import { useState } from "react";
import axios from "axios";

function App() {

  const [message, setMessage] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {

    if (!message) return;

    setLoading(true);

    try {

      const res = await axios.post(
        "http://127.0.0.1:8000/api/chat",
        {
          message: message
        }
      );

      setResponse(res.data.response);

    } catch (error) {

      console.log(error);

      setResponse("Backend connection error");

    }

    setLoading(false);
  };

  return (

    <div className="min-h-screen bg-slate-950 text-white flex flex-col items-center p-10">

      <h1 className="text-5xl font-bold mb-10 text-cyan-400">
        AI College Companion
      </h1>

      <div className="w-full max-w-3xl bg-slate-900 p-6 rounded-2xl shadow-2xl">

        <textarea
          rows="4"
          placeholder="Ask anything about studies, placements, coding..."
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          className="w-full p-4 rounded-xl bg-slate-800 text-white border border-slate-700 focus:outline-none"
        />

        <button
          onClick={sendMessage}
          className="mt-4 bg-cyan-500 hover:bg-cyan-600 px-6 py-3 rounded-xl font-semibold"
        >
          Ask AI
        </button>

        <div className="mt-8 bg-slate-800 p-5 rounded-xl min-h-[200px]">

          <h2 className="text-2xl font-semibold mb-4 text-cyan-300">
            Response
          </h2>

          {
            loading ? (
              <p className="animate-pulse text-gray-400">
                AI is thinking...
              </p>
            ) : (
              <p className="leading-8 whitespace-pre-wrap">
                {response}
              </p>
            )
          }

        </div>

      </div>

    </div>
  );
}

export default App;
